import { d as db } from "../../../../../chunks/db.js";
import { g as getEmpresaId } from "../../../../../chunks/get-empresa-id.js";
const load = async ({ request, url }) => {
  const empresaId = await getEmpresaId(request);
  const page = Number(url.searchParams.get("page")) || 1;
  const limit = Number(url.searchParams.get("limit")) || 20;
  const skip = (page - 1) * limit;
  const acao = url.searchParams.get("acao");
  const usuarioId = url.searchParams.get("usuarioId");
  const search = url.searchParams.get("search");
  const dataInicio = url.searchParams.get("dataInicio");
  const dataFim = url.searchParams.get("dataFim");
  const where = {
    documento: {
      empresaId
    }
  };
  if (acao && acao !== "all") {
    where.acao = acao;
  }
  if (usuarioId && usuarioId !== "all") {
    where.usuarioId = usuarioId;
  }
  if (search) {
    where.OR = [
      { documento: { numero: { contains: search, mode: "insensitive" } } },
      { descricao: { contains: search, mode: "insensitive" } }
    ];
  }
  if (dataInicio || dataFim) {
    where.createdAt = {};
    if (dataInicio) {
      where.createdAt.gte = new Date(dataInicio);
    }
    if (dataFim) {
      const endDate = new Date(dataFim);
      endDate.setHours(23, 59, 59, 999);
      where.createdAt.lte = endDate;
    }
  }
  const [logs, total] = await Promise.all([
    db.logDocumento.findMany({
      where,
      include: {
        usuario: {
          select: {
            id: true,
            name: true,
            email: true
          }
        },
        documento: {
          select: {
            id: true,
            numero: true,
            tipoDocumento: true
          }
        }
      },
      orderBy: {
        createdAt: "desc"
      },
      take: limit,
      skip
    }),
    db.logDocumento.count({ where })
  ]);
  const users = await db.user.findMany({
    where: {
      empresaId
    },
    select: {
      id: true,
      name: true
    }
  });
  const actionsResult = await db.logDocumento.findMany({
    where: {
      documento: {
        empresaId
      }
    },
    select: {
      acao: true
    },
    distinct: ["acao"]
  });
  const actions = actionsResult.map((a) => a.acao);
  return {
    logs,
    pagination: {
      page,
      limit,
      total,
      totalPages: Math.ceil(total / limit)
    },
    filters: {
      users,
      actions
    }
  };
};
export {
  load
};
